  const cx = Math.min(0.9, Math.max(0.1, P.x)) * L + (fr(n * 7 + 2) - 0.5) * L * 0.7;
  const cy = Math.min(0.9, Math.max(0.1, P.y)) + (fr(n * 7 + 3) - 0.5) * 0.7;
  const rr = (0.09 + fr(n * 7 + 4) * 0.07) * Math.max(0.4, P.scale);
  const sg = (n & 1) ? 1 : -1;
