  const r2 = rr * rr;
  const i0 = ((cx - rr) * sc) | 0, i1 = ((cx + rr) * sc) | 0;
  const j0 = Math.max(0, ((cy - rr) * sc) | 0), j1 = Math.min(BH - 1, ((cy + rr) * sc) | 0);
  for (let j = j0; j <= j1; j++) for (let ii = i0; ii <= i1; ii++) {
