// ---- 1. advect u, v and the flux function ----
for (let j = 0; j < BH; j++) {
  const jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const p = jc + i;
    const bx = i - U[p] * dt * sc, by = j - V[p] * dt * sc;
    U2[p] = samp(U, bx, by); V2[p] = samp(V, bx, by); A2[p] = samp(AA, bx, by);
