// ---- 2. Lorentz force J*grad(A), plus a large-scale drifting stir on incommensurate rates
const lor = (0.7 + en * 2.4) * 0.9;
const f1 = 0.30 * Math.sin(tt * 0.067) + 0.18 * Math.sin(tt * 0.151 + 1.3);
const f2 = 0.26 * Math.cos(tt * 0.089 + 0.7) + 0.15 * Math.sin(tt * 0.197 + 2.4);
const stir = (0.10 + en * 0.14);
for (let j = 1; j < BH - 1; j++) {
  const jm = (j - 1) * BW, jp = (j + 1) * BW, jc = j * BW;
  const y = (j + 0.5) / BH;
  for (let i = 0; i < BW; i++) {
    const im = i === 0 ? BW - 1 : i - 1, ip = i === BW - 1 ? 0 : i + 1, p = jc + i;
    const x = (i + 0.5) / BH;
    const lap = AA[jc + im] + AA[jc + ip] + AA[jm + i] + AA[jp + i] - 4 * AA[p];
    const jz = -lap;                                   // current density (grid units)
    JJ[p] = jz;
