  const jm = (j - 1) * BW, jp = (j + 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i === 0 ? BW - 1 : i - 1, ip = i === BW - 1 ? 0 : i + 1;
    U[jc + i] -= 0.5 * (PR[jc + ip] - PR[jc + im]) / h;
    V[jc + i] -= 0.5 * (PR[jp + i] - PR[jm + i]) / h;
  }
}
for (let i = 0; i < BW; i++) { V[i] = 0; V[(BH - 1) * BW + i] = 0; }

// ---- 4. viscosity + RESISTIVITY (this is the term that actually reconnects) ----
{
  const kv = Math.min(0.24, nuv * sc * sc * dt);
  const ke = Math.min(0.24, etaR * sc * sc * dt);
  const dec = 1 - Math.min(0.02, dt * 0.010);      // slow flux decay: ropes are injected forever
  U2.set(U); V2.set(V); A2.set(AA);
  for (let j = 0; j < BH; j++) {
    const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const im = i === 0 ? BW - 1 : i - 1, ip = i === BW - 1 ? 0 : i + 1, p = jc + i;
      U[p] = U2[p] + (U2[jc + im] + U2[jc + ip] + U2[jm + i] + U2[jp + i] - 4 * U2[p]) * kv;
      V[p] = V2[p] + (V2[jc + im] + V2[jc + ip] + V2[jm + i] + V2[jp + i] - 4 * V2[p]) * kv;
      AA[p] = (A2[p] + (A2[jc + im] + A2[jc + ip] + A2[jm + i] + A2[jp + i] - 4 * A2[p]) * ke) * dec;
    }
  }
