// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + Math.sin(tt * 0.021) * 10 + sec * 5) % 360 + 360) % 360;
function pal(m, sp2, off) {
  const hr = hb / 360 + off;
  return [0.5 + 0.5 * Math.cos(TAU * (m + hr)), 0.5 + 0.5 * Math.cos(TAU * (m + hr + sp2)), 0.5 + 0.5 * Math.cos(TAU * (m + hr + sp2 * 2))];
}
const cF = pal(0.02, 0.14, 0.0), cP = pal(0.52, 0.14, 0.0);
// Field lines ARE the contours of A: banding cos(A*n) draws them directly, no tracing needed.
// The spacing has to track A's own live amplitude, though — reconnection and resistive decay
// swing the flux range by 4x over a minute, so a FIXED n shows a dozen filaments one moment
// and a single smooth gradient the next.
let arms = 0;
for (let p = 0; p < NC; p++) arms += AA[p] * AA[p];
arms = Math.sqrt(arms / NC);
const nb = TAU * (3.5 + en * 9) / Math.max(0.015, arms * 2.5);
const jsc = 2.6 + en * 5.0;
const gl = 0.86 + A.treble * 0.35 + K.swell * 0.1;

